SELECT amount_bucket, txn_cohort, unique_merchants FROM (SELECT CASE WHEN amount >= 4100 THEN 'high' WHEN amount >= 1700 THEN 'mid' ELSE 'low' END AS amount_bucket, CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END AS txn_cohort, COUNT(DISTINCT amount) AS unique_merchants FROM transactions GROUP BY CASE WHEN amount >= 4100 THEN 'high' WHEN amount >= 1700 THEN 'mid' ELSE 'low' END, CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END) AS sub WHERE unique_merchants < 8 ORDER BY unique_merchants DESC, amount_bucket ASC, txn_cohort ASC LIMIT 10
